package com.mentality.fabricwebmap.web;
import org.junit.jupiter.api.Test;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;
class BiomeRequestControlTest {private String js()throws Exception{return Files.readString(Path.of("src/main/resources/web/app.js"));}@Test void rapidMouseMovementProducesBoundedBiomeRequests()throws Exception{assertTrue(js().contains("BIOME_THROTTLE_MS = 150")&&js().contains("clearTimeout"));}@Test void biomeCacheKeyIncludesDimension()throws Exception{assertTrue(js().contains("currentDimension + ':' + blk.x + ':' + blk.z"));}@Test void dimensionSwitchInvalidatesBiomeState()throws Exception{assertTrue(js().contains("_biomeLastBlock = null"));}@Test void staleBiomeResponseCannotOverwriteNewerRequest()throws Exception{assertTrue(js().contains("serial === _biomeRequestSerial"));}}
